-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 12
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 12 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 12', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 12 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-12.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que é público-alvo e por que projetar para "todo mundo" é um erro.', 0.2, 'Público-alvo é o recorte demográfico e comportamental das pessoas que usam o produto para resolver uma necessidade real. Projetar para "todo mundo" é erro porque cada grupo tem rotinas, limitações tecnológicas e paciência diferentes.', 'Nota cheia: define público-alvo como recorte de pessoas com necessidade real e explica que "todo mundo" leva a atender ninguém bem, com grupos diferentes. Metade: define o termo ou explica o erro, mas só um dos dois. Zero: em branco, definição errada ou fora do tema.'),
      (v_atividade, 1, 2, 'Descreva dois perfis de uso, citando limitações, aparelho e contexto de cada um.', 0.4, 'Dois perfis da página de agendamento, como o "Estudante com Pressa" (usa em pé, com conexão móvel instável e sol na tela, precisa de contraste alto e confirmação em 1 toque) e o "Paciente Cuidadoso" (prioriza fontes legíveis, explicações claras de cada campo e receio de cometer enganos). Cada perfil com limitação, aparelho e contexto.', 'Nota cheia: descreve dois perfis distintos, citando para cada um limitação, aparelho e contexto de uso. Metade: descreve dois perfis, mas omite um dos três elementos ou fica genérico. Zero: em branco, um perfil só ou perfis sem relação com o celular e o agendamento.'),
      (v_atividade, 1, 3, 'Indique um cuidado de design que atenda a cada perfil descrito.', 0.4, 'Um cuidado de design para cada perfil. Para quem tem pressa: contraste alto e confirmação em 1 toque. Para quem é cuidadoso: fontes legíveis e explicação clara de cada campo, com aviso antes de ações que cancelem o serviço.', 'Nota cheia: indica um cuidado de design coerente para cada um dos dois perfis descritos no item b. Metade: indica cuidado para só um perfil ou cuidados genéricos sem ligação com o perfil. Zero: em branco ou cuidado que não tem relação com os perfis.'),
      (v_atividade, 2, 1, 'Diferencie objetivo primário (core task) de objetivo secundário (suporte).', 0.2, 'Objetivo primário (core task) é a ação indispensável que levou a pessoa a abrir o aplicativo, como marcar a consulta no horário desejado. Objetivo secundário (suporte) é a ação complementar que ajuda o sistema mas não motivou a entrada, como editar a foto de perfil.', 'Nota cheia: diferencia os dois com as próprias palavras, mostrando que o primário é o motivo da entrada e o secundário é complementar. Metade: define só um dos dois ou diferencia de forma vaga. Zero: em branco ou definições trocadas.'),
      (v_atividade, 2, 2, 'Classifique pelo menos três tarefas da tela nos dois grupos.', 0.4, 'Classificação de pelo menos três tarefas da tela. Primário: marcar o horário (data e hora). Secundário: trocar a foto de perfil e outras ações de suporte, como avaliar o aplicativo.', 'Nota cheia: classifica corretamente pelo menos três tarefas, com marcação do horário no primário e tarefas complementares no secundário. Metade: classifica duas tarefas corretamente ou uma está no grupo errado. Zero: em branco ou tudo no mesmo grupo.'),
      (v_atividade, 2, 3, 'Explique qual deve ter destaque visual e por quê.', 0.4, 'O destaque visual deve ir para a marcação do horário, porque é a tarefa urgente que motivou a entrada. A foto de perfil deve ficar com menos destaque, pois não é a ação que o usuário veio cumprir.', 'Nota cheia: indica o horário como destaque e justifica pela tarefa primária ser o motivo da entrada. Metade: indica o destaque certo sem justificativa, ou justifica sem indicar a tarefa. Zero: em branco ou destaque na tarefa secundária.'),
      (v_atividade, 3, 1, 'Nomeie as cinco fases típicas de uma jornada digital, na ordem.', 0.2, 'As cinco fases, na ordem: 1) Acesso, 2) Busca, 3) Seleção, 4) Confirmação, 5) Pós-uso.', 'Nota cheia: lista as cinco fases na ordem correta. Metade: lista quatro fases corretas ou tem uma troca de ordem. Zero: em branco ou fases fora da aula.'),
      (v_atividade, 3, 2, 'Associe a cada fase uma ação prática que o usuário executa.', 0.4, 'Acesso: entrar no link ou no app. Busca: localizar o serviço. Seleção: escolher data e dados. Confirmação: enviar e validar o pedido. Pós-uso: receber comprovante e lembrete.', 'Nota cheia: associa cada uma das cinco fases a uma ação prática coerente com a jornada do caso. Metade: associa três ou quatro fases corretamente. Zero: em branco ou ações que não correspondem às fases.'),
      (v_atividade, 3, 3, 'Explique por que a fase de confirmação precisa de um retorno claro.', 0.4, 'Na confirmação o usuário precisa saber se o agendamento deu certo. Sem retorno claro, ele não tem como saber se o horário foi reservado e tende a agendar de novo ou a ligar para a recepção.', 'Nota cheia: explica que o retorno claro evita dúvida sobre o agendamento e evita duplicidade ou ligação, com as próprias palavras. Metade: diz que o retorno é importante sem explicar o efeito. Zero: em branco ou explicação que não se relaciona à confirmação.'),
      (v_atividade, 4, 1, 'Nomeie as quatro camadas da jornada.', 0.2, 'As quatro camadas são: ações práticas, pensamentos, emoções e pontos de atrito.', 'Nota cheia: nomeia as quatro camadas corretamente. Metade: nomeia três camadas corretamente. Zero: em branco ou camadas inventadas.'),
      (v_atividade, 4, 2, 'Dê um exemplo de ação prática e um de pensamento do usuário nessa tarefa.', 0.4, 'Ação prática: digitar o CPF ou escolher a data no calendário. Pensamento: "Será que esse horário ainda está livre? Quanto vai custar?".', 'Nota cheia: dá um exemplo de ação prática e um de pensamento, ambos ligados ao agendamento. Metade: dá só um dos dois exemplos ou exemplos genéricos. Zero: em branco ou exemplos que não são de ação ou pensamento.'),
      (v_atividade, 4, 3, 'Dê um exemplo de emoção e um de ponto de atrito, explicando o efeito de cada um.', 0.4, 'Emoção: ansiedade ao ver o calendário sem avisar horários ocupados (ou alívio ao confirmar). Ponto de atrito: campo que apaga tudo ou erro sem explicação. O efeito da emoção é levar ao abandono; o efeito do atrito é travar a ação.', 'Nota cheia: dá um exemplo de emoção e um de atrito e explica o efeito de cada um. Metade: dá os dois exemplos sem explicar o efeito, ou explica só um. Zero: em branco ou exemplos fora da jornada.'),
      (v_atividade, 5, 1, 'Descreva as etapas da curva de humor, da motivação à desistência.', 0.2, 'As etapas da curva são: 1) Motivação, 2) Primeira dúvida, 3) Atrito crítico, 4) Desistência, 5) Frustração total.', 'Nota cheia: descreve as etapas da motivação até a desistência, na ordem. Metade: descreve parte das etapas ou fora de ordem. Zero: em branco ou etapas que não existem na aula.'),
      (v_atividade, 5, 2, 'Relacione cada etapa a um evento concreto da tela.', 0.4, 'Motivação: vontade de agendar ao abrir a página. Primeira dúvida: o campo confuso. Atrito crítico: o erro sem explicação. Desistência: abandono do processo.', 'Nota cheia: relaciona cada etapa a um evento concreto da tela descrito no caso. Metade: relaciona três etapas corretamente. Zero: em branco ou eventos que não estão no caso.'),
      (v_atividade, 5, 3, 'Indique em qual etapa agir primeiro e proponha uma melhoria para ela.', 0.4, 'A intervenção deve começar no atrito crítico (erro não explicado), que é o pico de estresse antes da desistência. Melhoria: mostrar mensagem clara explicando o erro e como corrigi-lo, sem perder os dados já preenchidos.', 'Nota cheia: indica o atrito crítico como etapa prioritária e propõe melhoria concreta para ela. Metade: indica a etapa certa sem melhoria, ou melhoria sem a etapa. Zero: em branco ou etapa e melhoria sem relação com o caso.'),
      (v_atividade, 6, 1, 'Defina pesquisa quantitativa e qualitativa.', 0.2, 'Pesquisa quantitativa trabalha com números e mostra quantas pessoas fazem algo e onde o problema ocorre. Pesquisa qualitativa trabalha com motivos e mostra o porquê do comportamento.', 'Nota cheia: define os dois tipos com as próprias palavras, com números no primeiro e motivos no segundo. Metade: define só um dos tipos corretamente. Zero: em branco ou definições trocadas.'),
      (v_atividade, 6, 2, 'Dê um exemplo de pergunta que cada tipo de dado responde.', 0.4, 'Quantitativa: "Quantas pessoas desistiram na tela de pagamento?" (ou no agendamento). Qualitativa: "Por que você desistiu naquela tela?".', 'Nota cheia: dá uma pergunta para cada tipo, coerente com o que cada um responde. Metade: dá uma pergunta correta e a outra errada ou genérica. Zero: em branco ou perguntas que não se encaixam nos tipos.'),
      (v_atividade, 6, 3, 'Explique por que os números sozinhos não bastam para decidir a melhoria.', 0.4, 'Os números mostram onde o abandono acontece, mas não revelam o motivo. Sem entender o porquê com os usuários, a equipe pode corrigir o ponto errado.', 'Nota cheia: explica que o número mostra o onde e não o porquê, e que isso pode levar a decisão errada. Metade: diz que os números não bastam sem explicar o motivo. Zero: em branco ou resposta que contraria a aula.'),
      (v_atividade, 7, 1, 'Explique por que a pergunta é induzida e que resposta ela força.', 0.2, 'A pergunta é induzida (enviesada) porque força o entrevistado a concordar por vergonha de parecer confuso ou desagradável. Ela induz a resposta "sim, foi fácil".', 'Nota cheia: explica que a pergunta induz a concordar e diz qual resposta ela força. Metade: diz que é induzida sem explicar a resposta forçada. Zero: em branco ou classifica a pergunta como neutra.'),
      (v_atividade, 7, 2, 'Reescreva a pergunta de forma aberta e neutra sobre a mesma tarefa.', 0.4, 'Exemplo de pergunta aberta e neutra: "Como foi para você localizar a opção de horário nessa tela?".', 'Nota cheia: reescreve de forma aberta, sem julgamento e sobre a mesma tarefa de localizar o botão ou o horário. Metade: reescreve de forma neutra, mas fechada (sim ou não). Zero: em branco ou pergunta que ainda induz a resposta.'),
      (v_atividade, 7, 3, 'Diga que tipo de informação a nova pergunta permite obter.', 0.4, 'A pergunta aberta e neutra revela dúvidas, hesitações e dificuldades reais do usuário, com liberdade para se expressar.', 'Nota cheia: diz que a nova pergunta traz dificuldades, dúvidas ou hesitações reais. Metade: diz só que traz "opinião" ou "informação" sem especificar. Zero: em branco ou informação que a pergunta não permite obter.'),
      (v_atividade, 8, 1, 'Explique a dica de entrevista sobre passado e futuro.', 0.2, 'A dica de entrevista é perguntar sobre o que a pessoa fez no passado, nunca sobre o que ela acha que faria no futuro.', 'Nota cheia: diz que se pergunta o passado e não o futuro, com as próprias palavras. Metade: menciona a dica sem deixar claro passado e futuro. Zero: em branco ou dica inventada.'),
      (v_atividade, 8, 2, 'Diga por que a pergunta sobre o que a pessoa faria é menos confiável.', 0.4, 'A pergunta sobre o futuro é pouco confiável porque a pessoa responde com uma intenção, que pode mudar, e não com um fato vivido. Ela tende a dizer o que parece agradável ou esperado.', 'Nota cheia: explica que a intenção futura não reflete o comportamento real. Metade: diz que é menos confiável sem explicar o motivo. Zero: em branco ou explicação que contraria a aula.'),
      (v_atividade, 8, 3, 'Reescreva-a perguntando sobre uma experiência passada concreta.', 0.4, 'Exemplo de pergunta sobre o passado: "Da última vez que você tentou agendar algo pelo celular, o que aconteceu no momento de escolher o horário?".', 'Nota cheia: reescreve perguntando sobre uma experiência passada concreta, ligada ao agendamento pelo celular. Metade: pergunta sobre o passado, mas genérica ou ainda com "usaria". Zero: em branco ou pergunta sobre o futuro.'),
      (v_atividade, 9, 1, 'Cite uma das regras de ouro da entrevista com usuários.', 0.2, 'Uma das regras de ouro: não defenda o design; abrace o silêncio; observe as reações. Também vale: anotar exatamente as palavras do entrevistado.', 'Nota cheia: cita uma regra de ouro correta da aula. Metade: cita uma ideia próxima, mas sem nomear a regra. Zero: em branco ou regra inventada.'),
      (v_atividade, 9, 2, 'Explique por que defender o design prejudica a pesquisa.', 0.4, 'Defender o design faz o entrevistado se sentir julgado e o leva a não dar sua opinião real. A pesquisa deixa de revelar a dificuldade verdadeira, porque o foco vira convencer.', 'Nota cheia: explica que defender o design inibe a fala sincera e distorce o resultado. Metade: diz que é errado sem explicar o efeito na pesquisa. Zero: em branco ou resposta que justifica defender o design.'),
      (v_atividade, 9, 3, 'Descreva o que fazer no lugar, incluindo a observação de reações.', 0.4, 'Agradecer, anotar a frase exata do colega, dar tempo para pensar e observar as reações (hesitação do dedo, mudança na respiração, olhar procurando algo).', 'Nota cheia: descreve agradecer ou anotar a fala e observar reações ou silêncio. Metade: descreve só um dos dois elementos. Zero: em branco ou conduta de defender ou sugerir solução.'),
      (v_atividade, 10, 1, 'Responda se a pergunta é adequada para pesquisa com o usuário.', 0.2, 'Não. A pergunta não é adequada para pesquisa com o usuário, porque induz a resposta positiva.', 'Nota cheia: responde "não" (inadequada) com justificativa. Metade: responde "não" sem justificar. Zero: em branco ou responde que é adequada.'),
      (v_atividade, 10, 2, 'Explique o viés que a pergunta provoca na resposta.', 0.4, 'O viés é de confirmação: a pergunta já afirma que o menu ficou bonito e pede que o usuário concorde, o que leva a uma resposta positiva por vergonha ou para agradar.', 'Nota cheia: explica que a pergunta induz concordância e positiva a resposta. Metade: diz que há viés sem explicar como ele age. Zero: em branco ou viés que não se aplica.'),
      (v_atividade, 10, 3, 'Diga qual informação ela deixa de revelar sobre a dificuldade real.', 0.4, 'A pergunta não revela se o usuário teve dificuldade real com a cor, nem em que momento ela atrapalhou a tarefa.', 'Nota cheia: diz que a pergunta não revela a dificuldade real com a cor ou com a tarefa. Metade: diz que falta informação sem especificar qual. Zero: em branco ou informação que a pergunta de fato revela.'),
      (v_atividade, 11, 1, 'Escreva uma pergunta sobre contexto e hábito de uso.', 0.2, 'Pergunta sobre contexto e hábito, como: "Quando foi a última vez que você tentou agendar algo pelo celular? Como foi essa experiência?".', 'Nota cheia: escreve pergunta aberta e neutra sobre contexto ou hábito de uso do agendamento pelo celular. Metade: pergunta sobre hábito, mas induzida ou fechada. Zero: em branco ou pergunta fora do tema.'),
      (v_atividade, 11, 2, 'Escreva uma pergunta para detectar atrito no preenchimento.', 0.4, 'Pergunta sobre atrito, como: "Em que momento do preenchimento você sentiu mais dúvida ou vontade de fechar a tela?".', 'Nota cheia: escreve pergunta aberta e neutra que busca o ponto exato de dúvida ou abandono no preenchimento. Metade: pergunta sobre atrito, mas fechada ou induzida. Zero: em branco ou pergunta fora do objetivo.'),
      (v_atividade, 11, 3, 'Explique o objetivo de cada pergunta com suas palavras.', 0.4, 'A primeira pergunta entende o ambiente real de uso (em casa, na rua, com pressa). A segunda mapeia o ponto exato da dor sem sugerir respostas.', 'Nota cheia: explica o objetivo de cada pergunta com as próprias palavras, ligado a contexto e a atrito. Metade: explica só uma das perguntas ou o objetivo é vago. Zero: em branco ou objetivo que não corresponde às perguntas.'),
      (v_atividade, 12, 1, 'Diga qual é a regra de condução do entrevistador.', 0.2, 'A regra de condução é: o entrevistador não pode opinar; apenas ouve, anota e observa.', 'Nota cheia: diz que o entrevistador não opina e só ouve e anota. Metade: diz só que deve ouvir, sem a parte de não opinar. Zero: em branco ou conduta de opinar ou sugerir.'),
      (v_atividade, 12, 2, 'Explique o que anotar durante a fala do colega.', 0.4, 'Anotar exatamente as palavras do colega (a frase exata da maior dificuldade) e as hesitações observadas.', 'Nota cheia: diz que deve anotar as palavras exatas e as hesitações. Metade: diz só um dos dois. Zero: em branco ou anotar a própria opinião.'),
      (v_atividade, 12, 3, 'Explique por que sugerir uma solução atrapalha o resultado.', 0.4, 'Sugerir solução interrompe a fala do colega, faz ele responder ao que o entrevistador pensa e tira a chance de conhecer a dificuldade real.', 'Nota cheia: explica que a sugestão interrompe e direciona a resposta, prejudicando o resultado. Metade: diz que atrapalha sem explicar como. Zero: em branco ou justifica a sugestão.'),
      (v_atividade, 13, 1, 'Explique o que é tabular os resultados coletados.', 0.2, 'Tabular é organizar os resultados coletados em categorias, com a contagem de cada uma, para que apareçam padrões e a queixa mais frequente.', 'Nota cheia: explica que tabular é agrupar e contar os resultados para ver padrões. Metade: diz que é organizar sem falar em contagem ou padrão. Zero: em branco ou definição fora do tema.'),
      (v_atividade, 13, 2, 'Agrupe os relatos em pelo menos três categorias de queixa.', 0.4, 'Pelo menos três categorias de queixa, como: excesso de dados, falta de comprovante (sem confirmação) e botão escondido ou difícil de achar, com os relatos agrupados em cada uma.', 'Nota cheia: agrupa os relatos em três ou mais categorias coerentes com o caso. Metade: agrupa em duas categorias. Zero: em branco ou categorias sem ligação com o caso.'),
      (v_atividade, 13, 3, 'Indique a queixa mais frequente e explique como ela orienta a prioridade.', 0.4, 'A queixa mais frequente é a de Data/Hora (17 relatos, na tabela da aula), seguida de excesso de dados (14). Ela orienta a prioridade porque é o problema que mais afeta os usuários e deve ser resolvido primeiro.', 'Nota cheia: indica a queixa de Data/Hora (17) como a mais frequente e explica que ela define a prioridade. Metade: indica a queixa mais frequente sem explicar a prioridade, ou cita excesso de dados (14) como a mais frequente. Zero: em branco ou queixa que não é a mais frequente sem justificativa.'),
      (v_atividade, 14, 1, 'Escreva a dor identificada, em uma frase.', 0.2, '"O usuário tem medo de o agendamento não ter sido feito."', 'Nota cheia: escreve a dor em uma frase, ligada ao medo de o agendamento não ter sido concluído. Metade: escreve a dor de forma vaga. Zero: em branco ou dor que não está no caso.'),
      (v_atividade, 14, 2, 'Proponha uma solução de interface que responda a essa dor.', 0.4, 'Tela final com ícone de check animado e botão "Adicionar ao calendário", que confirma o agendamento.', 'Nota cheia: propõe solução de interface que mostra a confirmação de forma clara, como check animado e botão de calendário. Metade: propõe confirmação genérica, sem elemento concreto. Zero: em branco ou solução que não confirma.'),
      (v_atividade, 14, 3, 'Explique como essa solução elimina o atrito, ligando-a à jornada.', 0.4, 'A confirmação visível elimina a dúvida na etapa de confirmação da jornada, evitando que o usuário agende de novo ou ligue para a recepção.', 'Nota cheia: liga a solução à etapa de confirmação e ao atrito eliminado. Metade: liga à jornada sem explicar o atrito eliminado. Zero: em branco ou explicação sem relação com a jornada.'),
      (v_atividade, 15, 1, 'Cite o dado de desistência que sustenta o argumento.', 0.2, 'Taxa de desistência de 60% das pessoas que abandonam o processo antes de concluir.', 'Nota cheia: cita o dado de desistência do caso (mais de 60%). Metade: cita a desistência sem o número. Zero: em branco ou dado inventado.'),
      (v_atividade, 15, 2, 'Explique como a pesquisa mostra a relação entre campos excessivos e abandono.', 0.4, 'Os depoimentos e as queixas mostram que usuários no celular desistem de formulários longos. Os dados da queda na etapa do calendário e o pedido de dados que a pessoa não tem em mãos ligam o excesso de campos ao abandono.', 'Nota cheia: liga o excesso de campos ao abandono com um dado ou queixa da pesquisa. Metade: afirma a relação sem apoiar em dado da pesquisa. Zero: em branco ou relação que a pesquisa não mostra.'),
      (v_atividade, 15, 3, 'Proponha uma alternativa para coletar os dados depois, com justificativa.', 0.4, 'Coletar só nome e telefone no começo e pedir os dados complementares depois, na sala de espera ou por confirmação de WhatsApp, com justificativa de que isso não atrasa o agendamento.', 'Nota cheia: propõe coletar os dados depois, em outro momento, com justificativa ligada ao abandono. Metade: propõe a alternativa sem justificativa. Zero: em branco ou alternativa que mantém todos os campos no início.'),
      (v_atividade, 16, 1, 'Defina achismo no design.', 0.2, 'Achismo é a decisão tomada pelo gosto pessoal da equipe ou do cliente, sem teste com usuários, que gera telas bonitas mas inutilizáveis.', 'Nota cheia: define achismo como decisão por gosto ou opinião, sem evidência. Metade: define de forma vaga ("é uma opinião"). Zero: em branco ou definição que não se aplica.'),
      (v_atividade, 16, 2, 'Compare decisão por gosto com decisão baseada em fatos.', 0.4, 'Decisão por gosto baseia-se na preferência de quem decide. Decisão baseada em fatos parte de atritos reais comprovados por pesquisa e observação.', 'Nota cheia: compara as duas formas de decidir, com a evidência como diferença. Metade: compara sem deixar claro o papel da evidência. Zero: em branco ou comparação que não se sustenta.'),
      (v_atividade, 16, 3, 'Diga qual tipo de evidência deve sustentar a decisão da equipe.', 0.4, 'A decisão deve ser sustentada por evidência coletada com usuários reais: pesquisa, observação e testes de protótipo que mostrem os atritos.', 'Nota cheia: indica evidência de pesquisa ou observação com usuários reais. Metade: indica evidência genérica ("dados") sem o usuário. Zero: em branco ou gosto da equipe como evidência.'),
      (v_atividade, 17, 1, 'Diga qual é a primeira etapa do mapeamento.', 0.2, 'A primeira etapa é identificar o público-alvo e seu objetivo primário.', 'Nota cheia: diz que a primeira etapa é identificar o público-alvo e o objetivo primário. Metade: cita uma etapa do meio ou do fim como primeira. Zero: em branco ou etapa que não é a primeira.'),
      (v_atividade, 17, 2, 'Ordene as demais etapas do mapeamento da jornada.', 0.4, 'Ordem das demais etapas: 2) listar as ações que o usuário executa passo a passo; 3) mapear pensamentos, emoções e atritos em cada etapa; 4) propor melhorias de design para eliminar os atritos.', 'Nota cheia: ordena as três etapas restantes corretamente. Metade: acerta duas posições. Zero: em branco ou ordem que inverte a lógica do mapeamento.'),
      (v_atividade, 17, 3, 'Explique por que a proposta de melhoria vem depois do mapeamento.', 0.4, 'A proposta de melhoria vem depois porque só se sabe o que corrigir depois de mapear as ações, os pensamentos, as emoções e os atritos. Propor antes seria achismo.', 'Nota cheia: explica que a melhoria depende do mapeamento e que propor antes é achismo. Metade: diz que a ordem é lógica sem explicar a dependência. Zero: em branco ou justificativa que contraria a aula.'),
      (v_atividade, 18, 1, 'Descreva o contexto de uso dessa pessoa.', 0.2, 'A pessoa usa o aplicativo em pé, com conexão instável e sol forte na tela, para marcar um horário antes de uma reunião.', 'Nota cheia: descreve o contexto com os três elementos (em pé, conexão instável, sol na tela) e a pressa. Metade: descreve dois dos elementos. Zero: em branco ou contexto que não é o do caso.'),
      (v_atividade, 18, 2, 'Liste as necessidades de contraste e de confirmação que esse contexto exige.', 0.4, 'Contraste alto para ler com sol na tela; confirmação em 1 toque, para não exigir várias ações em conexão instável.', 'Nota cheia: lista uma necessidade de contraste e uma de confirmação, ligadas ao contexto. Metade: lista só uma das duas. Zero: em branco ou necessidades que não vêm do contexto.'),
      (v_atividade, 18, 3, 'Diga duas decisões de design que atendem a essas necessidades.', 0.4, 'Duas decisões de design: contraste alto nos textos e botões; botão de confirmação em um toque, com alvo grande e mensagem clara de sucesso.', 'Nota cheia: dá duas decisões concretas, cada uma ligada a uma necessidade do item b. Metade: dá uma decisão concreta ou duas genéricas. Zero: em branco ou decisões que não atendem ao contexto.'),
      (v_atividade, 19, 1, 'Cite uma dor ligada ao tamanho do alvo de toque no celular.', 0.2, 'Dor ligada ao tamanho do alvo de toque: datas com menos de 44 px de altura provocam toques errados em dias indesejados (ou o menu suspenso minúsculo, difícil de tocar no ônibus).', 'Nota cheia: cita dor de alvo pequeno ou difícil de tocar, ligada ao celular. Metade: cita dor de toque sem ligação com o tamanho. Zero: em branco ou dor que não está no caso.'),
      (v_atividade, 19, 2, 'Cite uma dor ligada à falta de feedback após a ação.', 0.4, 'Dor ligada à falta de feedback: sem mensagem imediata de sucesso, o usuário agenda duas vezes ou liga para a recepção.', 'Nota cheia: cita a dor de agendar duas vezes ou ligar por falta de confirmação imediata. Metade: cita falta de feedback sem o efeito. Zero: em branco ou dor que não está no caso.'),
      (v_atividade, 19, 3, 'Proponha uma mudança de interface para cada dor citada.', 0.4, 'Para a dor 1: alvos de toque com pelo menos 44 px de altura (ou 48 px nas pills de horário). Para a dor 2: mensagem imediata de sucesso após o agendamento, com o horário confirmado na tela.', 'Nota cheia: propõe uma mudança de interface concreta para cada dor citada no item a e no item b. Metade: propõe mudança para só uma dor ou mudança genérica. Zero: em branco ou mudança sem relação com as dores.'),
      (v_atividade, 20, 1, 'Descreva o público-alvo claro que você definiu.', 0.2, 'Público-alvo claro: pessoas com pressa, que usam o celular em pé, em contexto instável, e pacientes cuidadosos, que temem erros. Cada perfil com limitações, aparelho e contexto.', 'Nota cheia: descreve um público-alvo claro com limitação, aparelho e contexto de uso. Metade: descreve o público de forma genérica ("pacientes"). Zero: em branco ou público que não tem relação com o caso.'),
      (v_atividade, 20, 2, 'Resuma a jornada mapeada, com as principais fases e atritos.', 0.4, 'Jornada mapeada com as fases de acesso, busca, seleção, confirmação e pós-uso, e os atritos principais: campos excessivos, alvo de toque pequeno e falta de feedback, além do calendário que não avisa horários ocupados.', 'Nota cheia: resume a jornada com as fases principais e pelo menos dois atritos do caso. Metade: resume as fases sem atritos, ou atritos sem fases. Zero: em branco ou resumo que não corresponde à jornada.'),
      (v_atividade, 20, 3, 'Explique como a pesquisa neutra sustenta as decisões do resumo.', 0.4, 'A pesquisa neutra, com perguntas abertas e sem indução, revela o uso real e sustenta as decisões do resumo. As decisões se apoiam em dados e relatos reais, e não em gosto.', 'Nota cheia: explica que perguntas abertas e neutras trazem evidência real que sustenta as decisões, em oposição ao achismo. Metade: diz que a pesquisa ajuda sem ligar à decisão. Zero: em branco ou explicação que defende perguntas induzidas.');
end $$;
